// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"sort"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown or Stop has been called.
var ErrStopped = errors.New("the job runner is stopped")

// stopTimeout is how long Stop waits for running jobs before it cancels them.
const stopTimeout = 30 * time.Second

// entry is a job that Enqueue accepted. seq keeps enqueue order.
type entry struct {
	seq int
	job Job
}

// active is a job that a worker is running.
type active struct {
	cancel   context.CancelFunc
	canceled bool // set by Shutdown when it cancels the job
}

// Runner runs jobs on its workers.
type Runner struct {
	workers   int
	queueSize int
	log       *slog.Logger

	mu      sync.Mutex
	cond    *sync.Cond // signaled when a job is queued or the runner closes
	seq     int
	closed  bool                 // Shutdown has been called
	idle    int                  // workers waiting for a job
	waiting []entry              // accepted, not started, in enqueue order
	running map[*active]struct{} // started, not finished
	failed  []entry              // canceled by Shutdown and returned an error
	wg      sync.WaitGroup       // the workers
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	r := &Runner{workers: workers, queueSize: queueSize, log: log, running: map[*active]struct{}{}}
	r.cond = sync.NewCond(&r.mu)
	return r
}

// Start starts the workers. It does nothing after Shutdown.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return
	}
	for i := 0; i < r.workers; i++ {
		r.wg.Add(1)
		go r.work()
	}
}

func (r *Runner) work() {
	defer r.wg.Done()
	for {
		r.mu.Lock()
		r.idle++
		for len(r.waiting) == 0 && !r.closed {
			r.cond.Wait()
		}
		r.idle--
		if r.closed {
			// Jobs still waiting stay unstarted; Pending reports them.
			r.mu.Unlock()
			return
		}
		e := r.waiting[0]
		r.waiting = r.waiting[1:]
		ctx, cancel := context.WithCancel(context.Background())
		a := &active{cancel: cancel}
		r.running[a] = struct{}{}
		r.mu.Unlock()

		panicked, err := r.run(ctx, e.job)
		cancel()

		r.mu.Lock()
		delete(r.running, a)
		if a.canceled && err != nil && !panicked {
			r.failed = append(r.failed, e)
		}
		r.mu.Unlock()
	}
}

// run calls j. A panic is logged and reported as panicked; the worker goes on with the next job.
func (r *Runner) run(ctx context.Context, j Job) (panicked bool, err error) {
	defer func() {
		if v := recover(); v != nil {
			r.log.Error("job panicked", "job", j.Name, "panic", v)
			panicked = true
		}
	}()
	if err := j.Run(ctx); err != nil {
		r.log.Error("job failed", "job", j.Name, "err", err)
		return false, err
	}
	return false, nil
}

// Enqueue adds a job to the queue without waiting. It returns ErrStopped after Shutdown and
// ErrQueueFull when the queue has no room.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return ErrStopped
	}
	// An idle worker takes a job at once, so it does not use up queue room.
	if len(r.waiting) >= r.queueSize+r.idle {
		return ErrQueueFull
	}
	r.seq++
	r.waiting = append(r.waiting, entry{seq: r.seq, job: j})
	r.cond.Signal()
	return nil
}

// Shutdown stops the runner. From the call on, Enqueue returns ErrStopped and no waiting job is started.
// It waits for running jobs to finish. If ctx ends first, it cancels their contexts, waits for them to
// return, and returns ctx.Err(). A second call returns nil at once.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.closed {
		r.mu.Unlock()
		return nil
	}
	r.closed = true
	r.cond.Broadcast()
	r.mu.Unlock()

	done := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(done)
	}()
	select {
	case <-done:
		return nil
	case <-ctx.Done():
	}

	r.mu.Lock()
	r.log.Warn("shutdown timed out; canceling running jobs", "running", len(r.running))
	for a := range r.running {
		a.canceled = true
		a.cancel()
	}
	r.mu.Unlock()
	<-done
	return ctx.Err()
}

// Stop shuts the runner down, waiting up to 30 seconds for running jobs. It returns at once after the first call.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in enqueue order. Before Shutdown these are the queued
// jobs not started yet. After Shutdown they are the jobs never started, then the jobs that Shutdown canceled
// and that returned an error.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	sort.Slice(r.failed, func(i, j int) bool { return r.failed[i].seq < r.failed[j].seq })
	jobs := make([]Job, 0, len(r.waiting)+len(r.failed))
	for _, e := range r.waiting {
		jobs = append(jobs, e.job)
	}
	for _, e := range r.failed {
		jobs = append(jobs, e.job)
	}
	return jobs
}

