func TestShutdownDoesNotStartQueuedJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started, release := make(chan struct{}), make(chan struct{})
	defer close(release)
	if err := r.Enqueue(blocker("block", started, release)); err != nil {
		t.Fatal(err)
	}
	<-started
	var mu sync.Mutex
	var ran []string
	for _, name := range []string{"b", "c"} {
		if err := r.Enqueue(Job{Name: name, Run: func(context.Context) error {
			mu.Lock()
			ran = append(ran, name)
			mu.Unlock()
			return nil
		}}); err != nil {
			t.Fatal(err)
		}
	}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want DeadlineExceeded", err)
	}
	if len(ran) != 0 {
		t.Fatalf("queued jobs ran after Shutdown: %v", ran)
	}
	// Never started jobs come first, then the canceled job that returned an error.
	if p := names(r.Pending()); len(p) != 3 || p[0] != "b" || p[1] != "c" || p[2] != "block" {
		t.Fatalf("Pending = %v, want [b c block]", p)
	}
}

