func TestPanickingJobIsRecovered(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	var panics atomic.Int32
	if err := r.Enqueue(Job{Name: "boom", Run: func(context.Context) error {
		panics.Add(1)
		panic("boom")
	}}); err != nil {
		t.Fatal(err)
	}
	ran := make(chan struct{})
	if err := r.Enqueue(Job{Name: "after", Run: func(context.Context) error {
		close(ran)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	select {
	case <-ran:
	case <-time.After(5 * time.Second):
		t.Fatal("worker did not go on after a panic")
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	if n := panics.Load(); n != 1 {
		t.Fatalf("panicking job ran %d times, want 1", n)
	}
	if p := r.Pending(); len(p) != 0 {
		t.Fatalf("Pending = %v, want none", names(p))
	}
}

func TestStopReturnsAtOnceAfterShutdown(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started, release := make(chan struct{}), make(chan struct{})
	if err := r.Enqueue(blocker("slow", started, release)); err != nil {
		t.Fatal(err)
	}
	<-started
	firstErr := make(chan error, 1)
	go func() { firstErr <- r.Shutdown(context.Background()) }()
	waitFor(t, func() bool {
		return errors.Is(r.Enqueue(Job{Name: "probe", Run: func(context.Context) error { return nil }}), ErrStopped)
	})

	stopped := make(chan struct{})
	go func() {
		r.Stop()
		close(stopped)
	}()
	select {
	case <-stopped:
	case <-time.After(5 * time.Second):
		t.Fatal("Stop waited for the first Shutdown")
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatalf("second Shutdown = %v, want nil", err)
	}
	close(release)
	if err := <-firstErr; err != nil {
		t.Fatalf("first Shutdown = %v, want nil", err)
	}
}

func TestShutdownLeavesNoGoroutines(t *testing.T) {
	baseline := runtime.NumGoroutine()
	r := NewRunner(4, 10, nil)
	r.Start()
	for i := 0; i < 8; i++ {
		if err := r.Enqueue(Job{Name: "quick", Run: func(context.Context) error { return nil }}); err != nil {
			t.Fatal(err)
		}
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	waitFor(t, func() bool { return runtime.NumGoroutine() <= baseline })
}

